import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:tawheeed/features/audio_library/audio_library_config.dart';
import 'package:tawheeed/features/audio_library/audio_library_manifest.dart';

/// Parses a manifest generated by `tool/audio_library/build_manifest_from_bucket.py`
/// against a real ArvanCloud bucket listing.
///
/// The sample fixtures elsewhere in this directory use invented keys such as
/// `yaqeen/01-marefat-shenasi.opus`. Those never existed: the bucket holds the
/// original Persian file names (`yaqeen/23. چگونگی بحث با مخالفان.opus`), which
/// means every assumption about the ASCII-only key contract has to be proven
/// against the real thing instead of a tidy stand-in.
void main() {
  late AudioLibraryManifest manifest;

  setUpAll(() {
    final file = File(
      'test/features/audio_library/fixtures/arvan_yaqeen_index.json',
    );
    manifest = AudioLibraryManifest.fromJson(
      jsonDecode(file.readAsStringSync()) as Map<String, dynamic>,
    );
  });

  group('real bucket manifest parses', () {
    test('exposes every track the bucket listing reported', () {
      expect(manifest.version, 2);
      expect(manifest.categories, hasLength(1));
      expect(manifest.allTracks, hasLength(23));
    });

    test('ids are unique and in curriculum order', () {
      final ids = manifest.allTracks.map((t) => t.id).toList();
      expect(ids.toSet(), hasLength(ids.length), reason: 'ids must be unique');
      expect(
        ids,
        List.generate(
            23, (i) => 'yaqeen-${(i + 1).toString().padLeft(2, '0')}'),
      );
    });

    test('every track carries a non-zero size and a resolvable key', () {
      for (final t in manifest.allTracks) {
        expect(t.id, isNotEmpty);
        expect(t.title, isNotEmpty);
        expect(t.sizeBytes, greaterThan(0));
        expect(t.file, startsWith('yaqeen/'));
        expect(t.file, endsWith('.opus'));
      }
    });

    test('titles carry no leftover file-name numbering', () {
      // Two files use "4_" / "5_" instead of "4. " / "5. "; a title that kept
      // its prefix would show up on the card as "4_ نقد ...".
      for (final t in manifest.allTracks) {
        expect(t.title, isNot(matches(RegExp(r'^\d'))));
      }
      expect(
        manifest.allTracks.map((t) => t.title),
        contains('نقد برهان شر مساله ی شُرور در جهان'),
      );
    });

    test('the category resolves to its Persian label and teacher', () {
      final category = manifest.categories.first;
      expect(category.id, 'yaqeen');
      expect(category.displayTitle, 'رد شبهات');
      expect(AudioCategory.bylineForCategory(category.id), 'استاد مراد یوسفی');
    });
  });

  group('objectUrl encodes the real Persian keys', () {
    test('produces the exact URL the host answered 206 for', () {
      // Verified by hand against the live bucket: this URL returns 206 with
      // 1024 bytes and Accept-Ranges: bytes. If the encoding drifts, seeking
      // silently degrades to a full-body 200 response.
      const key = 'yaqeen/23. چگونگی بحث با مخالفان.opus';
      final url = AudioLibraryConfig.objectUrl(key);
      expect(
        url,
        endsWith(
          'yaqeen/23.%20'
          '%DA%86%DA%AF%D9%88%D9%86%DA%AF%DB%8C%20'
          '%D8%A8%D8%AD%D8%AB%20'
          '%D8%A8%D8%A7%20'
          '%D9%85%D8%AE%D8%A7%D9%84%D9%81%D8%A7%D9%86.opus',
        ),
      );
    });

    test('round-trips every key back out of the encoded path', () {
      for (final t in manifest.allTracks) {
        final url = AudioLibraryConfig.objectUrl(t.file);
        expect(url.contains(' '), isFalse,
            reason: 'a raw space breaks the request line');
        expect(
          Uri.decodeFull(Uri.parse(url).path),
          endsWith(t.file),
          reason: 'key did not survive encoding: ${t.file}',
        );
      }
    });

    test('is idempotent for a key that already has a leading slash', () {
      const key = 'yaqeen/1. معرفت شناسی.opus';
      expect(
        AudioLibraryConfig.objectUrl('/$key'),
        AudioLibraryConfig.objectUrl(key),
      );
    });
  });
}
